 sprite.name='Fotografía original del Octavia · silueta transparente';sprite.visible=false;group.add(sprite);
 const shadowMaterial=new THREE.MeshBasicMaterial({color:'#000000',transparent:true,opacity:.20,depthWrite:false}),shadow=new THREE.Mesh(new THREE.CircleGeometry(1,32),shadowMaterial);shadow.rotation.x=-Math.PI/2;shadow.scale.set(.92,2.15,1);shadow.position.y=.015;shadow.visible=false;group.add(shadow);const local=new THREE.Vector3();let selected='rear';
 group.userData.originalPhoto={sprite,update(camera,enabled=true){group.updateWorldMatrix(true,false);local.copy(camera.position);group.worldToLocal(local);const key=enabled?octaviaPhotoView(local.x,local.y,local.z,selected):null;for(const child of body)child.visible=!key;sprite.visible=shadow.visible=!!key;group.userData.photoBillboards=key?1:0;if(!key)return null;selected=key;uniforms.photoSpin.value=-(group.userData.photoDistance||0)/.335;const rims=OCTAVIA_PHOTOS[key].rims||[];for(const [i,name]of ['photoRimA','photoRimB'].entries()){const r=rims[i];uniforms[name].value.set(...(r?[r[0]/1280,1-r[1]/720,r[2]/1280,r[3]/720]:[0,0,0,0]));}group.userData.photoWheelAngle=uniforms.photoSpin.value;const dim=photoDimensions(key);sprite.material.map=atlas[key];sprite.center.set(dim.centerX,dim.centerY);sprite.scale.set(dim.width,dim.height,1);sprite.position.set(0,.02,key==='rear'?2.15:key==='front'?-2.15:0);sprite.userData.photoView=key;return key;},dispose(){material.dispose();shadowMaterial.dispose();shadow.geometry.dispose();}};
